def solve():
    n, m = map(int, input().split())
    table = [list(map(int, input().split())) for _ in range(n)]

    row_changes = []
    col_changes = []

    # Check each row and see if we need to change it
    for i in range(n):
        row_sum = sum(table[i])
        if row_sum < 0:
            row_changes.append(i + 1)
            for j in range(m):
                table[i][j] = -table[i][j]

    # Check each column and see if we need to change it
    for j in range(m):
        col_sum = 0
        for i in range(n):
            col_sum += table[i][j]
        if col_sum < 0:
            col_changes.append(j + 1)
            for i in range(n):
                table[i][j] = -table[i][j]

    # Output the results
    print(len(row_changes), *row_changes)
    print(len(col_changes), *col_changes)

solve()
